import React from 'react';
import { useTranslation } from 'react-i18next';

// --- DashboardHeader (SIMPLIFIED and integrated as a component for the menu button) ---
const DashboardHeader = ({ onMenuClick, isEasyMode, t }) => ( 
    <button
        onClick={onMenuClick}
        style={{ 
            padding: '8px',
            backgroundColor: 'transparent', 
            border: 'none', 
            cursor: 'pointer',
            fontSize: isEasyMode ? '36px' : '28px', 
            color: '#856404', // Match the text color
            marginLeft: 'auto', // Push the button to the far right
            transition: 'color 0.2s',
        }}
        onMouseOver={e => e.currentTarget.style.color = '#333'} 
        onMouseOut={e => e.currentTarget.style.color = '#856404'}
    >
        <span role="img" aria-label={t('general.menu')}>☰</span>
    </button>
);
// --- END DashboardHeader ---


// --- Icon Component Modification (No changes needed, included for context) ---
const Icon = ({ name, emoji, isActive, onClick, isProminent, isEasyMode, keyName, color = '#1A73E8', bgColor = '#E8F0FE' }) => {
    
    // ... Icon logic and styling remain the same ...
    const isColored = isActive || isProminent; 
    let iconColor = color;
    let iconBgColor = '#E8F0FE'; 
    
    if (keyName === "dashboard.emergency_info_card") {
        iconColor = '#DC3545';
        iconBgColor = '#FDE9E9';
    } else if (keyName === "medical_menu.access_card_short") {
        iconColor = '#1A73E8';
        iconBgColor = '#E8F0FE';
    } else if (keyName === "dashboard.medical_history_card") {
        iconColor = '#17A2B8';
        iconBgColor = '#E8F7F9';
    }
    
    const baseFontSize = isEasyMode ? 32 : 18;
    let labelFontSize = baseFontSize;

    if (name && name.length > 12) {
        labelFontSize = isEasyMode ? 24 : 16;
    }


    return (
        <div 
            onClick={onClick} 
            style={{
                padding: '25px', 
                margin: '15px',
                border: `5px solid ${isColored ? iconColor : '#e0e0e0'}`,
                borderRadius: '15px', 
                width: '40%',
                textAlign: 'center',
                backgroundColor: isColored ? iconBgColor : '#ffffff',
                filter: isColored ? 'none' : 'grayscale(80%)',
                opacity: isColored ? 1 : 0.7, 
                cursor: 'pointer',
                boxShadow: isColored ? `0 8px 15px ${iconColor}4D` : '0 2px 5px rgba(0, 0, 0, 0.1)',
                transition: 'all 0.3s',
                fontSize: `${labelFontSize}px`, 
            }}
        >
            <span role="img" aria-label={name} style={{fontSize: isEasyMode ? '85px' : '40px', display: 'block', marginBottom: '10px'}}>{emoji}</span>
            <p style={{fontWeight: 'bold', color: '#333', margin: 0}}>{name}</p>
        </div>
    );
};
// --- END Icon Component Modification ---


function Dashboard({ isEasyMode, goToMedical, onMenuClick, goToEmergencyInfo }) { 
    const { t } = useTranslation();

    const showAppointmentNotification = true; 
    
    // REFINED notificationStyle with Flexbox for layout
    const notificationStyle = {
        // Set the notification to occupy the top area of the screen without margin
        padding: '10px 10px 10px 20px', // Adjusted padding for better visual balance
        backgroundColor: '#FFF3CD', 
        color: '#856404', 
        cursor: 'pointer',
        fontSize: isEasyMode ? '24px' : '16px',
        fontWeight: 'bold',
        // Only round the bottom corners to align perfectly with the screen top
        borderBottomLeftRadius: '10px', 
        borderBottomRightRadius: '10px',
        borderLeft: '5px solid #FFC107', 
        borderRight: '5px solid #FFC107',
        borderBottom: '5px solid #FFC107',
        boxShadow: '0 4px 10px rgba(0,0,0,0.1)',
        zIndex: 10,
        animation: 'blink-alert 1.8s infinite alternate', 
        
        // Flexbox ensures content is aligned and spaced correctly
        display: 'flex', 
        alignItems: 'center',
        justifyContent: 'flex-start', // Start text on the left, let the button go to the right
        width: '100%',
        boxSizing: 'border-box',
    };


    return (
        <div style={{ position: 'relative' }}>

            {/* Notification Banner Container - No absolute position needed anymore */}
            {showAppointmentNotification && (
                <div onClick={goToMedical} style={notificationStyle}>
                    <div style={{
                        display: 'flex', 
                        flexDirection: 'column', 
                        alignItems: 'flex-start',
                        flexGrow: 1, // Allows the text content to take up the left space
                    }}>
                        <span role="img" aria-label={t('general.alert')} style={{fontSize: '24px', lineHeight: '1', display: 'block'}}>🔔</span>
                        <span style={{ fontSize: isEasyMode ? '20px' : '14px', lineHeight: '1.2'}}>{t('dashboard.appointment_soon_alert')}</span>
                        <span style={{ fontSize: isEasyMode ? '28px' : '18px', fontWeight: '900', marginTop: '2px'}}>{t('general.tap_here')}</span>
                    </div>
                    
                    {/* The Header (Menu Button) is integrated here and pushed to the right */}
                    <DashboardHeader onMenuClick={onMenuClick} isEasyMode={isEasyMode} t={t} />
                </div>
            )}
            {/* END Notification Banner Container */}

            {/* MAIN ICON GRID - Clean top margin for content below the banner */}
            <div style={{ 
                display: 'flex', 
                flexWrap: 'wrap', 
                justifyContent: 'center', 
                paddingTop: showAppointmentNotification ? '25px' : '40px', // Add necessary space below the banner
                paddingBottom: '40px' 
            }}>
                
                {/* Icons... */}
                <Icon 
                    name={t('medical_menu.access_card_short')} 
                    emoji="🏥" 
                    isActive={true} 
                    onClick={goToMedical} 
                    isEasyMode={isEasyMode}
                    keyName={'medical_menu.access_card_short'} 
                />
                
                <Icon 
                    name={t('dashboard.emergency_info_card')} 
                    emoji="🆘" 
                    isProminent={true} 
                    isActive={false} 
                    onClick={goToEmergencyInfo} 
                    isEasyMode={isEasyMode}
                    keyName={'dashboard.emergency_info_card'} 
                />
                
                <Icon 
                    name={t('dashboard.medical_history_card')} 
                    emoji="📜" 
                    isProminent={true} 
                    isActive={false} 
                    onClick={() => console.log('Medical History page route needed.')}
                    isEasyMode={isEasyMode}
                    keyName={'dashboard.medical_history_card'} 
                />
                
                <div style={{ width: '40%', margin: '15px', visibility: 'hidden' }}></div>
            </div>

            {/* CSS Animation */}
            <style jsx>{`
                @keyframes blink-alert {
                    0% { 
                        opacity: 1; 
                        box-shadow: 0 4px 15px rgba(255, 193, 7, 0.6); 
                        border-color: #FFC107;
                    }
                    50% { 
                        opacity: 0.8; 
                        box-shadow: 0 4px 5px rgba(0,0,0,0.1); 
                        border-color: #FFEB3B;
                    }
                    100% { 
                        opacity: 1; 
                        box-shadow: 0 4px 15px rgba(255, 193, 7, 0.6); 
                        border-color: #FFC107;
                    }
                }
            `}</style>
        </div>
    );
}

export default Dashboard;
